languages.javascript:
if ([...fill].length !== 1) throw new Error('Fill must be one character');
const missing = width - [...text].length;
return text + (missing > 0 ? fill.repeat(missing) : '');

languages.python:
if len(fill) != 1:
    raise ValueError("Fill must be one character")
return text + fill * max(0, width - len(text))

languages.csharp:
var units = 0;
foreach (var _ in fill.EnumerateRunes()) units++;
if (units != 1) throw new ArgumentException("Fill must be one character");
var length = 0;
foreach (var _ in text.EnumerateRunes()) length++;
return text + string.Concat(Enumerable.Repeat(fill, Math.Max(0, width - length)));

languages.cpp:
auto count = [](const std::string& s) { long long n = 0; for (unsigned char c : s) if ((c & 0xC0) != 0x80) n++; return n; };
if (count(fill) != 1) throw std::invalid_argument("Fill must be one character");
std::string padding;
for (long long i = count(text); i < width; i++) padding += fill;
return text + padding;

languages.rust:
if fill.chars().count() != 1 { panic!("Fill must be one character"); }
let missing = (width - text.chars().count() as i64).max(0) as usize;
return text + &fill.repeat(missing);

languages.java:
if (fill.codePointCount(0, fill.length()) != 1) throw new IllegalArgumentException("Fill must be one character");
long missing = width - text.codePointCount(0, text.length());
return text + (missing > 0 ? fill.repeat((int) missing) : "");

languages.go:
